(function(root,factory){
  const req=typeof module!=="undefined"&&module.exports;
  const core=req?require("./go-core.js"):root.NcGoCore;
  const style=req?require("./go-style.js"):root.NcGoStyle;
  const api=factory(core,style,req);
  if(req)module.exports=api;
  root.NcGoPersonalities=api;
})(typeof globalThis!=="undefined"?globalThis:this,function(C,St,isNode){
  "use strict";

  // The registry of play-style personalities fitted from the game records. The data is generated by
  // tools/style-fit.cjs and is pure data: if the file is missing the engine still runs, it simply has
  // no personalities to offer. That is deliberate — nothing in the search may depend on the corpus
  // being present.
  let SPECS=null;
  const CACHE=new Map();

  function load(payload){
    SPECS=payload&&Array.isArray(payload.personalities)?payload:null;
    CACHE.clear();
    return SPECS?SPECS.personalities.length:0;
  }

  if(isNode){
    try{load(require("./data/personalities.json"))}catch(error){SPECS=null}
  }else if(root.NcGoPersonalityData){
    load(root.NcGoPersonalityData);
  }

  const loaded=()=>!!SPECS;
  function list(){
    if(!SPECS)return[];
    return SPECS.personalities.map(spec=>({id:spec.id,name:spec.name,label:spec.label,
      stats:spec.stats,traits:spec.traits}));
  }
  function describe(id){
    if(!SPECS)return null;
    return SPECS.personalities.find(spec=>spec.id===id)||null;
  }

  // Personalities are cached per (id, dial setting): the flat pattern table costs a megabyte and a
  // few milliseconds to expand, and rebuilding it once per move would be visible in the clock.
  function get(id,{styleWeight=1,bookWeight=1,playoutWeight=1}={}){
    if(!id||!SPECS)return null;
    const key=`${id}:${styleWeight}:${bookWeight}:${playoutWeight}`;
    let personality=CACHE.get(key);
    if(personality)return personality;
    const spec=describe(id);
    if(!spec)return null;
    personality=St.createPersonality(spec,{styleWeight,bookWeight,playoutWeight});
    CACHE.set(key,personality);
    return personality;
  }

  // Resolve whatever the caller has: an id, an already-built personality, or nothing at all.
  function resolve(value,options){
    if(!value)return null;
    if(typeof value==="object")return value;
    return get(String(value),options);
  }

  const ids=()=>SPECS?SPECS.personalities.map(spec=>spec.id):[];

  return{load,loaded,list,ids,get,describe,resolve};
});
